float seed = 437585.453123;
float PI = 3.141592653589793;
float res = 10.; // how many sqrs along the x axes

float hash21(vec2 p) 
{
  p = mod(p, PI*20.);
  float a = (mod(43758.5453123 + seed, 37562.) + 13548.);
  float f = dot (p, vec2 (127.1, 351.7));
  return fract(sin(f)*a);
}

vec2 hash2(vec2 p) 
{
  p = mod(p, PI*20.);
  float a = (mod(43758.5453123 + seed, 37562.) + 13548.);
  p = vec2(dot (p, vec2 (127.1, 351.7)), dot(p, vec2(245.5, 304.4)));
  return fract(sin(p)*a);
}

vec3 hash23(vec2 p) {
  p = mod(p, PI*20.);
  float a = (mod(43758.5453123 + seed, 37562.) + 13548.);
  vec3 p3 = vec3(dot (p, vec2 (127.1, 351.7)), dot (p, vec2 (261.5, 183.3)), dot(p, vec2(245.5, 304.4)));
  return fract(sin(p3)*a);
}

vec2 hash32(vec3 p) {
  p = mod(p, PI*20.);
  float a = (mod(43758.5453123 + seed, 37562.) + 13548.);
  vec2 p2 = vec2(dot (p, vec3 (127.1, 351.7, 251.45)), dot (p, vec3 (261.5, 183.3, 376.89)));
  return fract(sin(p2)*a);
}
float hash31(vec3 p) {
  p = mod(p, PI*20.);
  float a = (mod(43758.5453123 + seed, 37562.) + 13548.);
  float f = dot (p, vec3 (127.1, 351.7, 251.45));
  return fract(sin(f)*a);
}

//6t5-15t4+10t3
float ease(float t)
{
  return t * t * t * (t * (t * 6. - 15.) + 10.);
}
vec2 ease(vec2 t)
{
  return vec2(ease(t.x), ease(t.y));
}
vec3 ease(vec3 t)
{
  return vec3(ease(t.x), ease(t.y), ease(t.z));
}
vec4 ease(vec4 t)
{
  return vec4(ease(t.x), ease(t.y), ease(t.z), ease(t.w));
}

float noise(vec2 point){
    vec2 fr = ease(fract(point));
    vec2 hi = ceil(point);
    vec2 lo = floor(point);

    return mix(
        mix(
            hash21(lo), 
            hash21(vec2(hi.x , lo.y)), 
            fr.x
        ), 
        mix(
            hash21(vec2(lo.x , hi.y)),
            hash21(hi),
            fr.x
        ), 
        fr.y
    );
}

float noise(vec3 point){
    vec3 fr = ease(fract(point));
    vec3 hi = ceil(point);
    vec3 lo = floor(point);

    return mix(
        mix(
            mix(
                hash31(lo), 
                hash31(vec3(hi.x , lo.yz)), 
                fr.x
            ), 
            mix(
                hash31(vec3(lo.x , hi.y, lo.z)),
                hash31(vec3(hi.xy, lo.z)),
                fr.x
            ), 
            fr.y
        ),
        mix(
            mix(
                hash31(vec3(lo.xy, hi.z)), 
                hash31(vec3(hi.x , lo.y, hi.z)), 
                fr.x
            ), 
            mix(
                hash31(vec3(lo.x , hi.yz)),
                hash31(hi),
                fr.x
            ), 
            fr.y
        ),
        fr.z
    );
}

float octal(vec3 uv, int octaves, float persistence)
{
    float total = 0.;
    float frequency = 1.;
    float amplitude = 1.;
    float maxValue = 0.;  // Used for normalizing result to 0.0 - 1.0
    for(int i=0;i<octaves;i++) {
        total += noise(uv * frequency) * amplitude;

        maxValue += amplitude;

        amplitude *= persistence;
        frequency *= 2.;
    }
    return total/maxValue;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = ((fragCoord - .5 * iResolution.xy) / (iResolution.x/res));

    /*vec3 col = vec3(
        (
            noise(uv)
          + noise(uv * 2.) * .5
          + noise(uv * 4.) * .25
          + noise(uv * 8.) * .125
        ) / 1.875
    );*/

    float r = 1.-abs((-octal(vec3(uv + vec2(sin(iTime / 10.), cos(iTime / 10.)) * 10., 500. + iTime / 5.0), 8, .5) + .5) * 2.);
    float g = 1.-abs((-octal(vec3(uv + vec2(sin(iTime / 10.), cos(500. + iTime / 10.)) * 10., 2. * iTime / 5.0), 8, .5) + .5) * 2.);
    float b = 1.-abs((-octal(vec3(uv + vec2(sin(500. + iTime / 10.), cos(iTime / 10.)) * 10., 2. * iTime / 5.0), 8, .5) + .5) * 2.);

    vec3 col = vec3(r, g, b);

    // Output to screen
    fragColor = vec4(col,1.0);
}
